"use client";

import { useCallback, useId, useRef, useState, type Ref } from "react";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { Check, ChevronDown, Globe2, TriangleAlert } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  thinkingPanelBounded,
  type ThinkingSource,
  type ThinkingStatus,
  type ThinkingStep,
} from "./thinking-panel-types";
import { useThinkingPanelMotion } from "./use-thinking-panel-motion";
import { ThinkingPanelSources } from "./thinking-panel-sources";

export type {
  ThinkingSource,
  ThinkingStatus,
  ThinkingStep,
} from "./thinking-panel-types";

gsap.registerPlugin(useGSAP);

export interface ThinkingPanelProps {
  sources?: readonly ThinkingSource[];
  steps?: readonly ThinkingStep[];
  status?: ThinkingStatus;
  elapsedSeconds?: number;
  expanded?: boolean;
  defaultExpanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
  visibleSources?: number;
  completionLabel?: string;
  errorMessage?: string;
  width?: number;
  stiffness?: number;
  damping?: number;
  speed?: number;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function ThinkingPanel({
  sources = [],
  steps = [],
  status = "thinking",
  elapsedSeconds,
  expanded,
  defaultExpanded = true,
  onExpandedChange,
  visibleSources = 4,
  completionLabel = "Finished thinking",
  errorMessage = "Something went wrong. Please try again.",
  width = 440,
  stiffness = 380,
  damping = 34,
  speed = 1,
  className,
  ref,
}: ThinkingPanelProps) {
  const uid = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const sourcesTriggerRef = useRef<HTMLButtonElement>(null);
  const clockRef = useRef({ accumulated: 0, started: 0 });
  const [seconds, setSeconds] = useState(0);
  const [ownExpanded, setOwnExpanded] = useState(defaultExpanded);
  const [showAllSources, setShowAllSources] = useState(false);
  const [initialExpanded] = useState(expanded ?? defaultExpanded);
  const isOpen = expanded ?? ownExpanded;
  const sourceLimit = Math.floor(
    thinkingPanelBounded(visibleSources, 4, 1, 50),
  );
  const displayedSources = showAllSources
    ? sources
    : sources.slice(0, sourceLimit);
  const remaining = Math.max(0, sources.length - sourceLimit);
  const elapsed = Math.floor(
    thinkingPanelBounded(
      elapsedSeconds ?? seconds,
      0,
      0,
      Number.MAX_SAFE_INTEGER,
    ),
  );
  const signature = JSON.stringify([
    displayedSources.map((source) => source.id),
    steps.map((step) => step.id),
    status,
    showAllSources,
  ]);

  useGSAP(
    () => {
      const clock = clockRef.current;
      if (elapsedSeconds !== undefined) return;
      if (status !== "thinking") {
        setSeconds(Math.floor(clock.accumulated / 1000));
        return;
      }
      clock.started = performance.now();
      let lastSecond = -1;
      const tick = () => {
        const next = Math.floor(
          (clock.accumulated + performance.now() - clock.started) / 1000,
        );
        if (next !== lastSecond) {
          lastSecond = next;
          setSeconds(next);
        }
      };
      gsap.ticker.add(tick);
      return () => {
        clock.accumulated += performance.now() - clock.started;
        gsap.ticker.remove(tick);
      };
    },
    { dependencies: [status, elapsedSeconds], revertOnUpdate: true },
  );

  useThinkingPanelMotion({
    rootRef,
    panelRef,
    contentRef,
    signature,
    expanded: isOpen,
    status,
    stiffness,
    damping,
    speed,
  });

  useGSAP(
    () => {
      if (!isOpen && contentRef.current?.contains(document.activeElement))
        triggerRef.current?.focus({ preventScroll: true });
    },
    { dependencies: [isOpen] },
  );

  const attachRef = useCallback(
    (node: HTMLDivElement | null) => {
      rootRef.current = node;
      if (typeof ref === "function") {
        const cleanup = ref(node);
        return () => {
          rootRef.current = null;
          if (typeof cleanup === "function") cleanup();
          else ref(null);
        };
      }
      if (ref) ref.current = node;
      return () => {
        rootRef.current = null;
        if (ref) ref.current = null;
      };
    },
    [ref],
  );

  const changeExpanded = (next: boolean) => {
    if (expanded === undefined) setOwnExpanded(next);
    onExpandedChange?.(next);
    if (!next) triggerRef.current?.focus({ preventScroll: true });
  };

  return (
    <div
      ref={attachRef}
      data-slot="thinking-panel"
      data-expanded={isOpen}
      data-status={status}
      role="region"
      aria-label="AI activity"
      className={cn(
        "relative max-w-full overflow-hidden rounded-2xl border border-zinc-200/80 bg-white text-[13px] leading-5 text-zinc-600 shadow-[0_8px_32px_-20px_#00000020] dark:border-white/[0.08] dark:bg-[#1b1b1d] dark:text-zinc-400 dark:shadow-[0_12px_40px_-20px_#00000050]",
        className,
      )}
      style={{ width: thinkingPanelBounded(width, 440, 240, 960) }}
      onKeyDown={(event) => {
        if (event.key !== "Escape" || !isOpen) return;
        event.preventDefault();
        event.stopPropagation();
        if (
          showAllSources &&
          event.target instanceof Node &&
          contentRef.current?.contains(event.target)
        ) {
          setShowAllSources(false);
          sourcesTriggerRef.current?.focus({ preventScroll: true });
        } else changeExpanded(false);
      }}
    >
      <button
        ref={triggerRef}
        type="button"
        aria-expanded={isOpen}
        aria-controls={`${uid}-content`}
        onClick={() => changeExpanded(!isOpen)}
        className="flex min-h-13 w-full cursor-pointer items-center gap-2.5 rounded-2xl px-4 text-left outline-none hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-violet-400 dark:hover:bg-white/[0.025]"
      >
        <span
          aria-hidden="true"
          className="grid size-3.5 shrink-0 grid-cols-3 gap-[2px] text-violet-500 dark:text-violet-400"
        >
          {Array.from({ length: 9 }, (_, index) => (
            <span
              key={index}
              data-thinking-pixel
              className="rounded-[1px] bg-current"
              style={{ opacity: 0.65 }}
            />
          ))}
        </span>
        <span className="font-medium text-zinc-700 dark:text-zinc-300">
          {status === "thinking"
            ? "Thinking"
            : status === "error"
              ? "Interrupted after"
              : "Worked for"}{" "}
          <span
            aria-hidden="true"
            className="font-normal tabular-nums text-zinc-500 dark:text-zinc-400"
          >
            {elapsed}s
          </span>
          <span className="sr-only">
            {status === "thinking" ? "in progress" : `${elapsed} seconds`}
          </span>
        </span>
        <ChevronDown
          data-thinking-chevron
          aria-hidden="true"
          className="ml-auto size-4 shrink-0 text-zinc-400"
          style={{
            transform: initialExpanded ? "rotate(0deg)" : "rotate(-90deg)",
          }}
        />
      </button>
      <div
        ref={panelRef}
        id={`${uid}-content`}
        inert={!isOpen}
        aria-hidden={!isOpen}
        className="overflow-hidden"
        style={{ height: initialExpanded ? "auto" : 0 }}
      >
        <div
          ref={contentRef}
          className="border-t border-zinc-100 px-4 pt-4 pb-4 dark:border-white/[0.055]"
        >
          <ol aria-label="Activity steps" className="space-y-0">
            <li
              data-thinking-row="sources"
              className="relative grid grid-cols-[14px_minmax(0,1fr)] gap-x-2.5 pb-3"
            >
              <span
                aria-hidden="true"
                className="absolute top-5 bottom-1 left-[6px] w-px bg-zinc-200 dark:bg-white/[0.09]"
              />
              <Globe2
                aria-hidden="true"
                className="mt-0.5 size-3.5 text-zinc-400 dark:text-zinc-500"
              />
              <div className="min-w-0">
                <p className="mb-2">
                  {sources.length
                    ? "Searched"
                    : status === "thinking"
                      ? "Searching sources…"
                      : "No sources searched"}
                </p>
                {sources.length > 0 && (
                  <ThinkingPanelSources
                    sources={displayedSources}
                    remaining={remaining}
                    showAll={showAllSources}
                    onToggle={() => setShowAllSources(!showAllSources)}
                    triggerRef={sourcesTriggerRef}
                    expanded={isOpen}
                    stiffness={stiffness}
                    damping={damping}
                    speed={speed}
                  />
                )}
              </div>
            </li>
            {steps.map((step, index) => (
              <li
                key={step.id}
                data-thinking-row={`step-${step.id}`}
                className="relative grid grid-cols-[14px_minmax(0,1fr)] items-start gap-x-2.5 pb-3"
              >
                <span
                  aria-hidden="true"
                  className="absolute top-4 bottom-0 left-[6px] w-px bg-zinc-200 dark:bg-white/[0.09]"
                />
                <span
                  aria-hidden="true"
                  data-thinking-active={
                    status === "thinking" && index === steps.length - 1
                      ? "true"
                      : undefined
                  }
                  className={cn(
                    "mx-auto mt-2 size-1.5 rounded-full",
                    status === "thinking" && index === steps.length - 1
                      ? "bg-violet-500 dark:bg-violet-400"
                      : "bg-zinc-300 dark:bg-zinc-600",
                  )}
                />
                <span className="min-w-0 break-words">{step.label}</span>
              </li>
            ))}
            {status !== "thinking" && (
              <li
                data-thinking-row="result"
                className="grid grid-cols-[14px_minmax(0,1fr)] items-start gap-x-2.5"
              >
                {status === "complete" ? (
                  <span
                    aria-hidden="true"
                    className="mt-0.5 flex size-3.5 items-center justify-center rounded-full bg-violet-500 dark:bg-violet-400"
                  >
                    <Check
                      className="size-2.5 text-white dark:text-zinc-950"
                      strokeWidth={3}
                    />
                  </span>
                ) : (
                  <TriangleAlert
                    aria-hidden="true"
                    className="mt-0.5 size-3.5 text-amber-600 dark:text-amber-400"
                  />
                )}
                <span className="font-medium text-zinc-700 dark:text-zinc-300">
                  {status === "complete" ? completionLabel : errorMessage}
                </span>
              </li>
            )}
          </ol>
        </div>
      </div>
      <span
        role={status === "error" ? "alert" : "status"}
        aria-atomic="true"
        className="sr-only"
      >
        {status === "complete"
          ? completionLabel
          : status === "error"
            ? errorMessage
            : (steps.at(-1)?.label ?? "Searching sources")}
      </span>
    </div>
  );
}

import type { ReactNode } from "react";

export interface ThinkingSource {
  id: string;
  label: string;
  href?: string;
  icon?: ReactNode;
}

export interface ThinkingStep {
  id: string;
  label: string;
}

export type ThinkingStatus = "thinking" | "complete" | "error";

export const thinkingPanelBounded = (
  value: number,
  fallback: number,
  min: number,
  max: number,
) => (Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback);

export function thinkingSourceUrl(href?: string) {
  if (!href) return undefined;
  try {
    const url = new URL(href);
    return url.protocol === "https:" || url.protocol === "http:"
      ? url.href
      : undefined;
  } catch {
    return undefined;
  }
}

"use client";

import { useRef, type RefObject } from "react";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { type ThinkingStatus } from "./thinking-panel-types";
import { thinkingPanelSpring } from "./thinking-panel-spring";

gsap.registerPlugin(useGSAP);

export function useThinkingPanelMotion({
  rootRef,
  panelRef,
  contentRef,
  signature,
  expanded,
  status,
  stiffness,
  damping,
  speed,
}: {
  rootRef: RefObject<HTMLDivElement | null>;
  panelRef: RefObject<HTMLDivElement | null>;
  contentRef: RefObject<HTMLDivElement | null>;
  signature: string;
  expanded: boolean;
  status: ThinkingStatus;
  stiffness: number;
  damping: number;
  speed: number;
}) {
  const syncRef = useRef<(() => void) | null>(null);

  useGSAP(
    () => {
      const root = rootRef.current;
      const panel = panelRef.current;
      const content = contentRef.current;
      if (!root || !panel || !content) return;
      const media = gsap.matchMedia();
      media.add(
        {
          reduced: "(prefers-reduced-motion: reduce)",
          standard: "(prefers-reduced-motion: no-preference)",
        },
        (context) => {
          const reduced = Boolean(context.conditions?.reduced);
          const { duration, ease } = thinkingPanelSpring(
            stiffness,
            damping,
            speed,
            reduced,
          );
          let timeline: gsap.core.Timeline | null = null;
          let positions = new Map<string, { top: number; left: number }>();
          let visible = true;
          const pulse = reduced
            ? null
            : gsap.to("[data-thinking-pixel]", {
                opacity: 0.2,
                duration: 0.6,
                stagger: { each: 0.08, repeat: -1, yoyo: true },
                ease: "sine.inOut",
                paused: true,
              });
          const updatePulse = () => {
            if (
              visible &&
              !document.hidden &&
              root.dataset.expanded === "true" &&
              root.dataset.status === "thinking"
            )
              pulse?.resume();
            else pulse?.pause();
          };
          const sync = context.add("sync", (immediate = false) => {
            const open = root.dataset.expanded === "true";
            const rows = Array.from(
              content.querySelectorAll<HTMLElement>(
                "[data-thinking-row], [data-thinking-source]",
              ),
            );
            const measurements = rows.map((row) => ({
              row,
              id: row.dataset.thinkingRow
                ? `row-${row.dataset.thinkingRow}`
                : `source-${row.dataset.thinkingSource}`,
              top: row.offsetTop,
              left: row.offsetLeft,
              x: Number(gsap.getProperty(row, "x")) || 0,
              y: Number(gsap.getProperty(row, "y")) || 0,
            }));
            const height = content.offsetHeight;
            timeline?.kill();
            timeline = gsap.timeline({
              defaults: {
                duration: immediate ? 0 : duration,
                ease,
                overwrite: "auto",
              },
            });
            timeline.to(panel, { height: open ? height : 0 }, 0);
            timeline.to(
              "[data-thinking-chevron]",
              { rotation: open ? 0 : -90 },
              0,
            );
            timeline.to(
              content,
              {
                opacity: open ? 1 : 0,
                duration: immediate || reduced ? 0 : 0.18,
                ease: "power2.out",
              },
              0,
            );
            for (const { row, id, top, left, x, y } of measurements) {
              const previous = positions.get(id);
              if (previous !== undefined)
                timeline.fromTo(
                  row,
                  { x: previous.left - left + x, y: previous.top - top + y },
                  { x: 0, y: 0, opacity: 1 },
                  0,
                );
              else if (!immediate && open)
                timeline.fromTo(
                  row,
                  { y: reduced ? 0 : 7, opacity: 0 },
                  {
                    y: 0,
                    opacity: 1,
                    duration: reduced ? 0 : Math.min(duration, 0.4),
                  },
                  0,
                );
            }
            positions = new Map(
              measurements.map(({ id, top, left }) => [id, { top, left }]),
            );
            updatePulse();
          });
          syncRef.current = () => sync();
          sync(true);
          const observer = new ResizeObserver(() => sync());
          observer.observe(content);
          const visibility = new IntersectionObserver(([entry]) => {
            visible = entry.isIntersecting;
            updatePulse();
          });
          visibility.observe(root);
          document.addEventListener("visibilitychange", updatePulse);
          return () => {
            observer.disconnect();
            visibility.disconnect();
            document.removeEventListener("visibilitychange", updatePulse);
            timeline?.kill();
            pulse?.kill();
            syncRef.current = null;
          };
        },
        root,
      );
      return () => media.revert();
    },
    {
      scope: rootRef,
      dependencies: [stiffness, damping, speed],
      revertOnUpdate: true,
    },
  );

  useGSAP(
    (context) => {
      context.ignore(() => syncRef.current?.());
    },
    { scope: rootRef, dependencies: [signature, expanded, status] },
  );
}

"use client";

import { useRef, type RefObject } from "react";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { Globe2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { thinkingSourceUrl, type ThinkingSource } from "./thinking-panel-types";
import { thinkingPanelSpring } from "./thinking-panel-spring";

gsap.registerPlugin(useGSAP);

export function ThinkingPanelSources({
  sources,
  remaining,
  showAll,
  onToggle,
  triggerRef,
  expanded,
  stiffness,
  damping,
  speed,
}: {
  sources: readonly ThinkingSource[];
  remaining: number;
  showAll: boolean;
  onToggle: () => void;
  triggerRef: RefObject<HTMLButtonElement | null>;
  expanded: boolean;
  stiffness: number;
  damping: number;
  speed: number;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const highlightRef = useRef<HTMLSpanElement>(null);

  useGSAP(
    () => {
      const root = rootRef.current;
      const highlight = highlightRef.current;
      if (!root || !highlight) return;
      const media = gsap.matchMedia();
      media.add(
        {
          reduced: "(prefers-reduced-motion: reduce)",
          standard: "(prefers-reduced-motion: no-preference)",
        },
        (context) => {
          const reduced = Boolean(context.conditions?.reduced);
          const physics = thinkingPanelSpring(
            stiffness,
            damping,
            speed,
            reduced,
          );
          let hovered = window.matchMedia("(hover: hover)").matches
            ? root.querySelector<HTMLElement>("[data-source-target]:hover")
            : null;
          let current: HTMLElement | null = null;
          let tween: gsap.core.Tween | null = null;
          const targetFor = (target: EventTarget | null) => {
            const item =
              target instanceof Element
                ? target.closest<HTMLElement>("[data-source-target]")
                : null;
            return item && root.contains(item) ? item : null;
          };
          const move = context.add("move", (force = false) => {
            if (hovered && !root.contains(hovered)) hovered = null;
            const target = expanded
              ? (hovered ?? targetFor(document.activeElement))
              : null;
            if (!force && target === current) return;
            tween?.kill();
            if (!target) {
              current = null;
              tween = gsap.to(highlight, {
                autoAlpha: 0,
                duration: reduced ? 0 : 0.16,
                ease: "power2.out",
                overwrite: true,
              });
              return;
            }
            const geometry = {
              x: target.offsetLeft,
              y: target.offsetTop,
              width: target.offsetWidth,
              height: target.offsetHeight,
            };
            if (!current || reduced)
              gsap.set(highlight, { ...geometry, scale: reduced ? 1 : 0.98 });
            current = target;
            tween = gsap.to(highlight, {
              ...geometry,
              scale: 1,
              autoAlpha: 1,
              ...physics,
              overwrite: true,
            });
          });
          const enter = (event: PointerEvent) => {
            if (event.pointerType === "touch") return;
            hovered = targetFor(event.target);
            move();
          };
          const leave = () => {
            hovered = null;
            move();
          };
          const focus = () => {
            hovered = null;
            move(true);
          };
          const blurInContext = context.add("blur", (event: FocusEvent) => {
            if (
              !root.contains(
                event.relatedTarget instanceof Node
                  ? event.relatedTarget
                  : null,
              )
            ) {
              hovered = null;
              current = null;
              tween?.kill();
              tween = gsap.to(highlight, {
                autoAlpha: 0,
                duration: reduced ? 0 : 0.16,
                overwrite: true,
              });
            } else move(true);
          });
          const blur = (event: FocusEvent) => blurInContext(event);
          const observer = new ResizeObserver(() => move(true));
          observer.observe(root);
          root
            .querySelectorAll<HTMLElement>("[data-source-target]")
            .forEach((target) => observer.observe(target));
          root.addEventListener("pointerover", enter);
          root.addEventListener("pointerleave", leave);
          root.addEventListener("focusin", focus);
          root.addEventListener("focusout", blur);
          move(true);
          return () => {
            observer.disconnect();
            root.removeEventListener("pointerover", enter);
            root.removeEventListener("pointerleave", leave);
            root.removeEventListener("focusin", focus);
            root.removeEventListener("focusout", blur);
            tween?.kill();
          };
        },
        root,
      );
      return () => media.revert();
    },
    {
      scope: rootRef,
      dependencies: [
        stiffness,
        damping,
        speed,
        expanded,
        JSON.stringify(sources.map(({ id, href }) => [id, href])),
      ],
      revertOnUpdate: true,
    },
  );

  const chipClass =
    "relative z-10 inline-flex min-h-7 max-w-full items-center gap-1.5 rounded-lg border border-zinc-200/80 bg-zinc-50/60 px-2 py-1 text-[11px] leading-4 text-zinc-600 pointer-coarse:min-h-10 dark:border-white/[0.07] dark:bg-white/[0.025] dark:text-zinc-300";
  return (
    <div
      ref={rootRef}
      data-thinking-sources
      className="relative isolate flex flex-wrap items-center gap-1.5"
    >
      <span
        ref={highlightRef}
        data-source-highlight
        aria-hidden="true"
        className="pointer-events-none absolute top-0 left-0 z-0 rounded-lg bg-zinc-200/80 opacity-0 shadow-[0_2px_8px_-4px_#00000025] dark:bg-white/[0.09]"
        style={{ visibility: "hidden", transformOrigin: "center" }}
      />
      {sources.map((source) => {
        const href = thinkingSourceUrl(source.href);
        const content = (
          <>
            <span
              data-source-logo
              aria-hidden="true"
              className="flex size-4 shrink-0 items-center justify-center overflow-hidden rounded-[3px] [&>svg]:size-full"
            >
              {source.icon ?? <Globe2 className="size-3.5" />}
            </span>
            <span className="truncate">{source.label}</span>
          </>
        );
        return href ? (
          <a
            key={source.id}
            data-thinking-source={source.id}
            data-source-target
            href={href}
            target="_blank"
            rel="noopener noreferrer"
            title={href}
            className={cn(
              chipClass,
              "outline-none focus-visible:ring-2 focus-visible:ring-violet-400",
            )}
          >
            {content}
            <span className="sr-only"> (opens in a new tab)</span>
          </a>
        ) : (
          <span
            key={source.id}
            data-thinking-source={source.id}
            data-source-target
            className={chipClass}
          >
            {content}
          </span>
        );
      })}
      {remaining > 0 && (
        <button
          ref={triggerRef}
          type="button"
          data-source-target
          aria-expanded={showAll}
          aria-label={
            showAll ? "Show fewer sources" : `Show ${remaining} more sources`
          }
          onClick={onToggle}
          className="relative z-10 min-h-7 cursor-pointer rounded-lg px-2 py-1 text-[11px] leading-4 text-zinc-500 outline-none focus-visible:ring-2 focus-visible:ring-violet-400 pointer-coarse:min-h-10 dark:text-zinc-400"
        >
          {showAll ? "Show less" : `+${remaining} more`}
        </button>
      )}
    </div>
  );
}

import { calcGeneratorDuration, spring } from "motion";
import { thinkingPanelBounded } from "./thinking-panel-types";

export function thinkingPanelSpring(
  stiffness: number,
  damping: number,
  speed: number,
  reduced: boolean,
) {
  const response = spring({
    keyframes: [0, 1],
    stiffness: thinkingPanelBounded(stiffness, 380, 120, 600),
    damping: thinkingPanelBounded(damping, 34, 20, 60),
    restSpeed: 0.001,
    restDelta: 0.001,
  });
  const settle = calcGeneratorDuration(response);
  return {
    duration: reduced
      ? 0
      : settle / 1000 / thinkingPanelBounded(speed, 1, 0.5, 2),
    ease: (progress: number) =>
      progress === 1 ? 1 : response.next(progress * settle).value,
  };
}
